#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main() {
    char s[3001], t[3001];
    scanf("%s %s", s, t);

    int n = strlen(s);
    int m = strlen(t);

    // dp[i][j] = length of LCS of s[0..i-1] and t[0..j-1]
    // Use short to save memory
    short **dp = (short **)malloc((n+1) * sizeof(short *));
    for (int i = 0; i <= n; i++) {
        dp[i] = (short *)calloc((m+1), sizeof(short));
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (s[i-1] == t[j-1]) {
                dp[i][j] = dp[i-1][j-1] + 1;
            } else {
                dp[i][j] = dp[i-1][j] > dp[i][j-1] ? dp[i-1][j] : dp[i][j-1];
            }
        }
    }

    int len = dp[n][m];
    char *result = (char *)malloc((len+1) * sizeof(char));
    result[len] = '\0';

    int i = n, j = m, k = len - 1;
    while (i > 0 && j > 0) {
        if (s[i-1] == t[j-1]) {
            result[k--] = s[i-1];
            i--;
            j--;
        } else if (dp[i-1][j] > dp[i][j-1]) {
            i--;
        } else {
            j--;
        }
    }

    printf("%s\n", result);

    for (int x = 0; x <= n; x++) {
        free(dp[x]);
    }
    free(dp);
    free(result);

    return 0;
