int main(void) {
    char s[3005], t[3005];
    if (scanf("%3000s %3000s", s, t) != 2) return 0;

    int n = (int)strlen(s);
    int m = (int)strlen(t);

    int *dp = (int *)calloc((n + 1) * (m + 1), sizeof(int));
    if (!dp) return 0;

    #define DP(i, j) dp[(i) * (m + 1) + (j)]

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            if (s[i - 1] == t[j - 1]) {
                DP(i, j) = DP(i - 1, j - 1) + 1;
            } else {
                DP(i, j) = DP(i - 1, j) > DP(i, j - 1) ? DP(i - 1, j) : DP(i, j - 1);
            }
        }
    }

    int len = DP(n, m);
    char *ans = (char *)malloc((len + 1) * sizeof(char));
    if (!ans) {
        free(dp);
        return 0;
    }
    ans[len] = '\0';

    int i = n, j = m, k = len - 1;
    while (i > 0 && j > 0) {
        if (s[i - 1] == t[j - 1]) {
            ans[k--] = s[i - 1];
            i--;
            j--;
        } else if (DP(i - 1, j) >= DP(i, j - 1)) {
            i--;
        } else {
            j--;
        }
    }

    printf("%s\n", ans);

    free(ans);
    free(dp);
    return 0;
}

