def main():
    data = sys.stdin.read().splitlines()
    if not data:
        return
    s = data[0].rstrip('\n')
    t = data[1].rstrip('\n') if len(data) > 1 else ""

    n, m = len(s), len(t)

    # dp[i][j] = length of LCS of s[:i] and t[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        si = s[i]
        row = dp[i + 1]
        prev_row = dp[i]
        for j in range(m):
            if si == t[j]:
                row[j + 1] = prev_row[j] + 1
            else:
                row[j + 1] = max(prev_row[j + 1], row[j])

    # Reconstruct one LCS
    i, j = n, m
    ans = []
    while i > 0 and j > 0:
        if s[i - 1] == t[j - 1]:
            ans.append(s[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    print(''.join(reversed(ans)))

